import {Config, Field} from 'alinea'

const CallToAction = Config.type('Call to action', {
  fields: {
    label: Field.text('Label'),
    link: Field.link('Link')
  }
})

export const Article = Config.document('Article', {
  fields: {
    body: Field.richText('Body', {
      searchable: true,
      enableTables: true,
      schema: {CallToAction}
    })
  }
})

