type TextDoc = Array<TextNode | ElementNode | BlockNode>

// Text, optionally with marks such as bold, italic or link
interface TextNode {
  _type: 'text'
  text?: string
  marks?: Array<{_type: string; [attr: string]: string | undefined}>
}

// Elements such as paragraph, heading or bulletList
interface ElementNode {
  _type: string
  content?: TextDoc
  [attr: string]: unknown
}

// Blocks from the schema option, e.g. an ImageBlock
interface BlockNode {
  _id: string
  _type: string
  [field: string]: unknown
}

