import type {TextDoc} from 'alinea'
import {RichText} from 'alinea/ui'
import Link from 'next/link'
import type {ComponentProps} from 'react'

function TextLink({href = '', ...props}: ComponentProps<'a'>) {
  return <Link href={href} {...props} />
}

function Heading2(props: ComponentProps<'h2'>) {
  return <h2 className="prose-h2" {...props} />
}

export function Prose({doc}: {doc: TextDoc}) {
  return (
    <RichText
      doc={doc}
      // Add a class to every paragraph
      p={<p className="prose-p" />}
      // Render h2 headings with your own component
      h2={Heading2}
      // Route links through next/link
      a={TextLink}
    />
  )
}

import {Config, Field, type Infer, type TextDoc} from 'alinea'
import {RichText} from 'alinea/ui'

const Quote = Config.type('Quote', {
  fields: {
    text: Field.text('Text', {multiline: true}),
    author: Field.text('Author')
  }
})

const blocks = {Quote}

export const Article = Config.document('Article', {
  fields: {
    body: Field.richText('Body', {schema: blocks})
  }
})

function QuoteView({text, author}: Infer<typeof Quote>) {
  return (
    <figure>
      <blockquote>{text}</blockquote>
      <figcaption>{author}</figcaption>
    </figure>
  )
}

export function Body({doc}: {doc: TextDoc}) {
  return <RichText<typeof blocks> doc={doc} Quote={QuoteView} />
}

import type {TextDoc} from 'alinea'
import {RichText} from 'alinea/ui'

export async function toHtml(doc: TextDoc) {
  const {renderToString} = await import('react-dom/server')
  return renderToString(<RichText doc={doc} />)
}

import {Field} from 'alinea'
import {formatting, links, lists} from 'alinea/field/richtext/Toolbar'

const {bold, italic, clear} = formatting.group

// A small editor for short texts: no headings, tables or images
export const summary = Field.richText('Summary', {
  toolbar: {
    formatting: {group: {bold, italic, clear}},
    lists,
    links
  }
})
